            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_true_regardless_of_order() {
        let options = vec![
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_other_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    #[test]
    fn ctrl_d_produces_unexpected_eof_error() {
        use crate::error::BivvyError;
        // Verify our EOF error matches the expected kind so callers can
        // distinguish Ctrl+D from other IO failures.
        let err = BivvyError::Io(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "end of input (Ctrl+D)",
        ));
        if let BivvyError::Io(ref io_err) = err {
            assert_eq!(io_err.kind(), std::io::ErrorKind::UnexpectedEof);
            assert!(io_err.to_string().contains("Ctrl+D"));
        } else {
            panic!("Expected BivvyError::Io");
        }
    }
}

